-- Explicit graph metadata for pristine built-in topics only; no content text/version changes.
UPDATE archdeck.flow_nodes n SET x=100,y=100,trust_zone='browser' FROM archdeck.content_items c WHERE n.content_id=c.id AND c.kind='topic' AND c.payload->>'legacyId'='keycloak-iam-overview' AND c.lock_version=0 AND n.node_key='user';
